{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2139-08-19 20:15:00",
      "speaker": "Doctor",
      "text": "Hello Mr. ___, I'm Dr. ___. You were admitted because your potassium was high and your kidney function is worse than usual. How are you feeling tonight?"
    },
    {
      "turn_number": 2,
      "time": "2139-08-19 20:16:00",
      "speaker": "Patient",
      "text": "I’m okay, no pain. But I’ve been tired and my legs are more swollen."
    },
    {
      "turn_number": 3,
      "time": "2139-08-19 20:17:00",
      "speaker": "Doctor",
      "text": "Yes, your labs show your creatinine is 3.2, which is higher than your usual 2.2. That means your kidneys aren’t filtering as well. Your potassium was 5.8, which is high. You got kayexelate before coming in, which helps lower it."
    },
    {
      "turn_number": 4,
      "time": "2139-08-19 20:18:00",
      "speaker": "Patient",
      "text": "Oh, okay. Is that why I feel so weak?"
    },
    {
      "turn_number": 5,
      "time": "2139-08-19 20:19:00",
      "speaker": "Doctor",
      "text": "That could be part of it. We also think the increase in your Lasix might have made your kidneys work harder, especially if you haven’t been eating much. We’re going to hold the Lasix for now and keep you on a low-sodium diet."
    },
    {
      "turn_number": 6,
      "time": "2139-08-19 20:20:00",
      "speaker": "Patient",
      "text": "I haven’t been hungry. My daughter said my blood sugar has been low too."
    },
    {
      "turn_number": 7,
      "time": "2139-08-19 20:21:00",
      "speaker": "Doctor",
      "text": "Yes, your glucose was 319 when you arrived, but your daughter told us she’s been holding your insulin because of low sugars at home. We’ll adjust your insulin while you’re here and restart it carefully before discharge."
    },
    {
      "turn_number": 8,
      "time": "2139-08-19 20:22:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. What about my legs? They’re red and blistered."
    },
    {
      "turn_number": 9,
      "time": "2139-08-19 20:23:00",
      "speaker": "Doctor",
      "text": "That looks like venous stasis dermatitis, which is common with your history of swelling. We’ll keep you in compression stockings and monitor it. No signs of infection right now."
    },
    {
      "turn_number": 10,
      "time": "2139-08-19 20:24:00",
      "speaker": "Patient",
      "text": "And my myeloma? I just had carfilzomib last week."
    },
    {
      "turn_number": 11,
      "time": "2139-08-19 20:25:00",
      "speaker": "Doctor",
      "text": "Yes, you’re on cycle 3, day 6. Your next dose is due in a few days. We’ll coordinate with oncology, but we may delay it slightly to make sure your kidneys are stable."
    },
    {
      "turn_number": 12,
      "time": "2139-08-19 20:26:00",
      "speaker": "Patient",
      "text": "I see. And my blood counts are low again?"
    },
    {
      "turn_number": 13,
      "time": "2139-08-19 20:27:00",
      "speaker": "Doctor",
      "text": "Yes, your hemoglobin is 8.3 and platelets are 36,000. That’s due to your myeloma and recent chemo. We won’t transfuse unless your hemoglobin drops below 7 or platelets below 10,000."
    },
    {
      "turn_number": 14,
      "time": "2139-08-19 20:28:00",
      "speaker": "Patient",
      "text": "Okay, I trust you. What about my blood pressure? My amlodipine was increased."
    },
    {
      "turn_number": 15,
      "time": "2139-08-19 20:29:00",
      "speaker": "Doctor",
      "text": "We held your amlodipine tonight because of your blood pressure and kidney concerns, but we’ll restart it tomorrow if things stabilize."
    },
    {
      "turn_number": 16,
      "time": "2139-08-20 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your potassium is now 4.7, which is normal. Your creatinine is still 3.2, but no worse. We’re continuing to hold Lasix and you’re on a low-sodium, low-potassium diet."
    },
    {
      "turn_number": 17,
      "time": "2139-08-20 08:16:00",
      "speaker": "Patient",
      "text": "That’s good. I feel a bit more energy today."
    },
    {
      "turn_number": 18,
      "time": "2139-08-20 08:17:00",
      "speaker": "Doctor",
      "text": "That’s great to hear. We gave you IV albumin yesterday because we thought you might be a little dehydrated. It seems to be helping your kidney perfusion."
    },
    {
      "turn_number": 19,
      "time": "2139-08-20 08:18:00",
      "speaker": "Patient",
      "text": "Oh, I didn’t know that. Is that safe with my kidneys?"
    },
    {
      "turn_number": 20,
      "time": "2139-08-20 08:19:00",
      "speaker": "Doctor",
      "text": "Yes, in small amounts it helps pull fluid into your bloodstream and supports kidney function. We used a low dose and monitored you closely."
    },
    {
      "turn_number": 21,
      "time": "2139-08-20 08:20:00",
      "speaker": "Patient",
      "text": "Okay, thanks. What about my liver? I remember last time I had transaminitis."
    },
    {
      "turn_number": 22,
      "time": "2139-08-20 08:21:00",
      "speaker": "Doctor",
      "text": "Good point. Your liver enzymes were normal when you came in, but we’re watching them. We held acyclovir because it can affect the liver, and we don’t want to add stress."
    },
    {
      "turn_number": 23,
      "time": "2139-08-20 08:22:00",
      "speaker": "Patient",
      "text": "Makes sense. I take a lot of meds. Hard to keep track."
    },
    {
      "turn_number": 24,
      "time": "2139-08-20 08:23:00",
      "speaker": "Doctor",
      "text": "We review them daily. You’re still on prednisone for your hemolytic anemia, atovaquone for PJP prevention, and allopurinol. Tamsulosin for your prostate too."
    },
    {
      "turn_number": 25,
      "time": "2139-08-20 08:24:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. And insulin?"
    },
    {
      "turn_number": 26,
      "time": "2139-08-20 08:25:00",
      "speaker": "Doctor",
      "text": "We’re giving sliding scale humalog for now. Once you’re eating better, we’ll restart your Tresiba at home. Your sugars have been stable today."
    },
    {
      "turn_number": 27,
      "time": "2139-08-21 09:00:00",
      "speaker": "Doctor",
      "text": "We did a kidney ultrasound yesterday. It shows your kidneys are small with thin cortices, which fits with chronic kidney disease. No blockage or stones. That supports our plan to manage this medically."
    },
    {
      "turn_number": 28,
      "time": "2139-08-21 09:01:00",
      "speaker": "Patient",
      "text": "So nothing’s blocked? That’s good."
    },
    {
      "turn_number": 29,
      "time": "2139-08-21 09:02:00",
      "speaker": "Doctor",
      "text": "No blockage. The issue seems to be reduced blood flow, likely from over-diuresis and low intake. Your creatinine is now 2.9, which is improving."
    },
    {
      "turn_number": 30,
      "time": "2139-08-21 09:03:00",
      "speaker": "Patient",
      "text": "That’s great. Can I go home soon?"
    },
    {
      "turn_number": 31,
      "time": "2139-08-21 09:04:00",
      "speaker": "Doctor",
      "text": "Possibly tomorrow. We want to make sure your potassium stays normal and your appetite improves. We’ll restart your amlodipine today and keep you on low-dose Lasix when you go home."
    },
    {
      "turn_number": 32,
      "time": "2139-08-21 09:05:00",
      "speaker": "Patient",
      "text": "And my myeloma treatment?"
    },
    {
      "turn_number": 33,
      "time": "2139-08-21 09:06:00",
      "speaker": "Doctor",
      "text": "We’ll resume carfilzomib after discharge. Your oncologist will coordinate the next dose. We’re holding off just to be safe with your kidneys."
    },
    {
      "turn_number": 34,
      "time": "2139-08-21 09:07:00",
      "speaker": "Patient",
      "text": "Okay, I’ll follow up with them."
    },
    {
      "turn_number": 35,
      "time": "2139-08-22 07:30:00",
      "speaker": "Doctor",
      "text": "Good news — your labs this morning show potassium 4.7, creatinine 2.9, and no signs of fluid overload. We’re discharging you today."
    },
    {
      "turn_number": 36,
      "time": "2139-08-22 07:31:00",
      "speaker": "Patient",
      "text": "That’s wonderful. What do I need to do at home?"
    },
    {
      "turn_number": 37,
      "time": "2139-08-22 07:32:00",
      "speaker": "Doctor",
      "text": "Continue compression stockings, daily weights, low-sodium diet, and hold Lasix unless your legs swell. Restart Tresiba and humalog as before. Follow up with nephrology and oncology."
    },
    {
      "turn_number": 38,
      "time": "2139-08-22 07:33:00",
      "speaker": "Patient",
      "text": "And if my weight goes up?"
    },
    {
      "turn_number": 39,
      "time": "2139-08-22 07:34:00",
      "speaker": "Doctor",
      "text": "If you gain more than 2 pounds in a day or have trouble breathing, call your doctor or come in. Otherwise, you’re doing well. It was good to see you."
    },
    {
      "turn_number": 40,
      "time": "2139-08-22 07:35:00",
      "speaker": "Patient",
      "text": "Thank you, doctor. I feel much better."
    }
  ],
  "summary": {
    "admission_start": "2139-08-19 20:12:00",
    "admission_end": "2139-08-22 13:11:00",
    "summary_paragraph": "Mr. ___, a male with relapsed multiple myeloma, chronic hemolytic anemia, type 2 diabetes, and stage 3 chronic kidney disease, was admitted for hyperkalemia and acute on chronic kidney injury with creatinine rising to 3.2 from a baseline of 2.2. The etiology was thought to be multifactorial, including recent uptitration of Lasix, decreased oral intake, and possible intravascular depletion. He received kayexelate prior to admission, and his potassium normalized. IV albumin was given for volume support. His creatinine improved to 2.9 by discharge. He was managed with holding diuresis, low-sodium diet, and compression stockings for chronic leg edema. His myeloma treatment with carfilzomib was held during admission and planned for resumption post-discharge. Pancytopenia persisted but remained stable without transfusion. Insulin was adjusted due to hypoglycemia at home, and Tresiba was restarted at discharge. He was discharged home in stable condition with follow-up arranged with nephrology and oncology.",
    "problems": [
      "Acute kidney failure, unspecified",
      "Hyperkalemia",
      "Multiple myeloma in relapse",
      "Type 2 diabetes mellitus with diabetic chronic kidney disease",
      "Chronic kidney disease, stage 3 (moderate)",
      "Venous insufficiency (chronic) (peripheral)",
      "Antineoplastic chemotherapy induced pancytopenia",
      "Nonspecific elevation of levels of transaminase and lactic acid dehydrogenase [LDH]"
    ]
  }
}
